import re
from typing import Dict, Optional

from.base import BasePatch
from.utils import is_buggy_line


class PythonFunctionPatch(BasePatch):
    def __init__(self, filename: str, function_name: str, buggy_line: int) -> None:
        super().__init__(filename, buggy_line)
        self._function_name = function_name

    @property
    def function_name(self) -> str:
        return self._function_name

    @classmethod
    def from_string(cls, string: str) -> Optional["PythonFunctionPatch"]:
        """
        >>> PythonFunctionPatch.from_string('##correct\ndef foo():\n    return 5\n##end-correct')
        PythonFunctionPatch('foo', 1)
        """
        matches = cls.pattern.findall(string)
        if not matches:
            return None
        matches = matches[0]
        return cls(matches[0], matches[1], int(matches[2]))

    def to_string(self) -> str:
        """
        >>> PythonFunctionPatch.from_string('##correct\ndef foo():\n    return 5\n##end-correct').to_string()
        '##correct\\ndef foo():\\n    return 5\\n##end-correct'
        """
        return re.sub(r'\\', r'\\\\', super().to_string())

    @staticmethod
    def get_type() -> str:
        return "function"

    def is_buggy_line(self, line: str) -> bool:
        return is_buggy_line(line, self.buggy_line)

    @property
    def lines(self) -> Dict[int, str]:
        return self.get_lines(self.buggy_line)

    @property
    def buggy_line_content(self) -> str:
        return self.get_line(self.buggy_line)
